#!/usr/bin/env python3
# Apply a Unity scene's root prefab instances, main camera and directional light to an
# existing s&box .scene, using prefabs already generated by UnityImporterPlus.
#
# usage: unity_scene_to_sbox.py <package.unitypackage> <Assets/Path/Scene.unity | /path/to/Scene.unity>
#                               <sbox Assets dir> <target .scene> [--replace NAME=GUID ...] [--allow-partial]
#
# The scene is read from the package by its Unity path, or from disk when the second argument
# is an existing file (use this when the Unity project is newer than the package export).
# Prefab GUIDs always resolve through the package. The target .scene is edited in place:
#   - each Unity root prefab instance becomes an s&box prefab instance of the generated
#     prefab. An existing instance is replaced (keeping its __guid) when its Name override
#     matches, or when named explicitly with --replace "<Unity instance name>=<scene __guid>"
#     (use this to swap out a hand-made instance). Otherwise a new instance is appended.
#   - the first CameraComponent object and the first DirectionalLight object are updated from
#     the first Unity camera and directional light.
# Everything else in the scene is kept. Line endings are preserved. Every change is printed;
# exits 1 when anything could not be converted, unless --allow-partial is given.
import json, math, re, sys, tarfile, uuid, os

M = 39.37  # inches per metre

def pos(u): return (u[2] * M, -u[0] * M, u[1] * M)
def rot(q): return (-q[2], q[0], -q[1], q[3])
def scl(s): return (s[2], s[0], s[1])
def fmt(v): return ",".join(repr(round(float(x), 6)).rstrip("0").rstrip(".") if x else "0" for x in v)

def srgb_to_linear(c): return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4

# Unity 6000.3 Mathf.CorrelatedColorTemperatureToRGB sampled every 500 K (Kelvin, r, g, b).
# Linear interpolation stays within 0.009 of Unity (its own curve fit is documented as 0.008).
CCT = [(1000, 1, 0.0416116, 0.00333669), (1500, 1, 0.146938, 0), (2000, 1, 0.253856, 0.0133016), (2500, 1, 0.358414, 0.066929),
       (3000, 1, 0.457798, 0.147839), (3500, 1, 0.550245, 0.24998), (4000, 1, 0.634856, 0.366719), (4500, 1, 0.711371, 0.491717),
       (5000, 1, 0.779967, 0.619521), (5500, 1, 0.841093, 0.745848), (6000, 1, 0.89534, 0.86761), (6500, 1, 0.943362, 0.98279),
       (7000, 0.910237, 0.90006, 1), (7500, 0.826545, 0.85172, 1), (8000, 0.76165, 0.812576, 1), (8500, 0.709879, 0.780241, 1),
       (9000, 0.667633, 0.753088, 1), (9500, 0.632521, 0.72997, 1), (10000, 0.602889, 0.710056, 1), (11000, 0.555661, 0.677519, 1),
       (12000, 0.519747, 0.652082, 1), (13000, 0.491563, 0.631673, 1), (14000, 0.468894, 0.614956, 1), (15000, 0.450297, 0.601027, 1),
       (17500, 0.415885, 0.574693, 1), (20000, 0.392443, 0.556273, 1), (25000, 0.36314, 0.532518, 1), (30000, 0.34621, 0.518215, 1),
       (40000, 0.329113, 0.502752, 1)]

def cct_rgb(kelvin):
    kelvin = min(max(kelvin, CCT[0][0]), CCT[-1][0])
    for a, b in zip(CCT, CCT[1:]):
        if a[0] <= kelvin <= b[0]:
            t = (kelvin - a[0]) / (b[0] - a[0])
            return [a[i] + (b[i] - a[i]) * t for i in (1, 2, 3)]

def blocks(text):
    out = {}
    for m in re.finditer(r"(?ms)^--- !u!(\d+) &(-?\d+)( stripped)?[^\n]*\n(.*?)(?=^--- |\Z)", text):
        out[int(m.group(2))] = (m.group(1), m.group(4), bool(m.group(3)))
    return out

def field(body, name):
    m = re.search(r"(?m)^\s*" + re.escape(name) + r":\s*(.*)$", body)
    return m.group(1).strip() if m else None

def vec(body, name, axes):
    m = re.search(r"(?m)^\s*" + re.escape(name) + r":\s*\{([^}]*)\}", body)
    d = dict(re.findall(r"(\w+):\s*(-?[0-9.eE+-]+)", m.group(1))) if m else {}
    return [float(d.get(a, 0)) for a in axes]

def ref_id(value): 
    m = re.search(r"fileID:\s*(-?\d+)", value or "")
    return int(m.group(1)) if m else 0

def ref_guid(value):
    m = re.search(r"guid:\s*([0-9a-fA-F]{32})", value or "")
    return m.group(1).lower() if m else None

def unquote(v):
    if len(v) >= 2 and v[0] == v[-1] == "'": return v[1:-1].replace("''", "'")
    if len(v) >= 2 and v[0] == v[-1] == '"': return bytes(v[1:-1], "utf-8").decode("unicode_escape")
    return v

def disk_path(root, rel):
    """The importer's own rule: reuse an existing file or folder in any case, otherwise lowercase."""
    current = root
    for part in rel.replace("\\", "/").split("/"):
        if not part: continue
        names = os.listdir(current) if os.path.isdir(current) else []
        match = next((n for n in (part.lower(), part) if n in names), None) or next((n for n in names if n.lower() == part.lower()), None)
        current = os.path.join(current, match or part.lower())
    return current

def main(argv):
    allow_partial = "--allow-partial" in argv
    argv = [a for a in argv if a != "--allow-partial"]
    replace = {}
    while "--replace" in argv:
        i = argv.index("--replace")
        name, _, guid = argv[i + 1].partition("=")
        replace[name] = guid
        del argv[i:i + 2]
    if len(argv) != 4: sys.exit("usage: unity_scene_to_sbox.py <package> <scene> <sbox Assets dir> <target .scene> [--replace NAME=GUID] [--allow-partial]")
    package, scene_in_package, assets_dir, target = argv
    problems = []

    # guid -> Unity path, and the scene text, straight from the package (tar.gz of guid/ dirs).
    paths, files = {}, {}
    with tarfile.open(package, "r:gz") as tar:
        for member in tar.getmembers():
            parts = member.name.strip("./").split("/")
            if len(parts) == 2 and parts[1] in ("pathname", "asset") and member.isfile():
                files[(parts[0].lower(), parts[1])] = tar.extractfile(member).read()
    for (guid, kind), data in files.items():
        if kind == "pathname": paths[guid] = data.decode("utf-8").splitlines()[0].strip()
    by_path = {p.lower(): g for g, p in paths.items()}
    if os.path.isfile(scene_in_package):
        # A .unity file on disk (e.g. the live Unity project) wins over the package copy, which
        # is only as new as the last export. Prefab GUIDs still resolve through the package.
        scene_text = open(scene_in_package, encoding="utf-8-sig").read()
        scene_guid = re.sub(r"\W", "", os.path.abspath(scene_in_package))[-32:]
        print(f"scene read from disk: {scene_in_package}")
    else:
        scene_guid = by_path.get(scene_in_package.lower())
        if not scene_guid: sys.exit(f"scene {scene_in_package} not found in package")
        scene_text = files[(scene_guid, "asset")].decode("utf-8")
        print(f"scene read from package: {paths[scene_guid]}")
    unity = blocks(scene_text.replace("\r\n", "\n"))
    if not any(c == "1001" for c, _, _ in unity.values()):
        problems.append("the Unity scene has no prefab instances; if the package predates your scene edits, re-export it or pass the .unity file path")

    raw = open(target, "rb").read()
    crlf = b"\r\n" in raw
    scene = json.loads(raw.decode("utf-8-sig"))
    objs = scene["GameObjects"]

    # --- Root prefab instances -> s&box prefab instance stubs ---------------------------
    for fid, (cls, body, _) in unity.items():
        if cls != "1001" or ref_id(field(body, "m_TransformParent")) != 0: continue
        src = ref_guid(field(body, "m_SourcePrefab"))
        unity_path = paths.get(src)
        if not unity_path:
            problems.append(f"prefab instance {fid}: source prefab {src} is not in the package"); continue
        rel = unity_path[len("Assets/"):] if unity_path.startswith("Assets/") else unity_path
        disk = disk_path(assets_dir, "Imported/" + rel)
        doc_path = ("imported/" + rel).lower()
        if not os.path.isfile(disk):
            problems.append(f"{unity_path}: generated prefab {disk} missing; run the importer first"); continue
        generated_root = json.load(open(disk, encoding="utf-8-sig"))["RootObject"]
        root_guid = generated_root["__guid"]
        # An instance starts from the source prefab root's own transform; the scene only lists what it changes.
        src_root = next((b for c, b, stripped in blocks(files.get((src, "asset"), b"").decode("utf-8", "replace")).values()
                         if c in ("4", "224") and not stripped and ref_id(field(b, "m_Father")) == 0), "")
        p = vec(src_root, "m_LocalPosition", "xyz") if src_root else [0.0, 0.0, 0.0]
        r = vec(src_root, "m_LocalRotation", "xyzw") if src_root else [0.0, 0.0, 0.0, 1.0]
        s = vec(src_root, "m_LocalScale", "xyz") if src_root else [1.0, 1.0, 1.0]
        name, active, skipped = os.path.splitext(os.path.basename(unity_path))[0], True, []
        for m in re.finditer(r"(?m)^\s*- target:\s*\{[^}]*\}\s*\n\s*propertyPath:\s*(\S+)\s*\n\s*value:[ \t]*([^\n]*?)[ \t]*$", body):
            path, value = m.group(1), unquote(m.group(2))
            axis = "xyzw".find(path[-1]) if len(path) > 2 and path[-2] == "." else -1
            if path.startswith("m_LocalPosition.") and 0 <= axis < 3: p[axis] = float(value)
            elif path.startswith("m_LocalRotation.") and axis >= 0: r[axis] = float(value)
            elif path.startswith("m_LocalScale.") and 0 <= axis < 3: s[axis] = float(value)
            elif path == "m_Name": name = value
            elif path == "m_IsActive": active = value != "0"
            elif path.startswith("m_LocalEulerAnglesHint") or path == "m_RootOrder": pass
            else: skipped.append(path)
        if skipped: problems.append(f"{name}: scene-level overrides not applied: {', '.join(sorted(set(skipped)))}")
        existing = next((o for o in objs if o.get("__guid") == replace.get(name)), None) or next((o for o in objs if "__Prefab" in o and any(
            po.get("Property") == "Name" and po.get("Value") == name
            for po in o.get("__PrefabInstancePatch", {}).get("PropertyOverrides", []))), None)
        if name in replace and existing is None: problems.append(f"--replace {name}: no object with __guid {replace[name]} in the target scene")
        instance_guid = existing["__guid"] if existing else str(uuid.uuid5(uuid.NAMESPACE_URL, f"unityimporterplus-scene:{scene_guid}:{fid}"))
        def ov(prop, value): return {"Target": {"Type": "GameObject", "IdValue": root_guid}, "Property": prop, "Value": value}
        overrides = [ov("Position", fmt(pos(p))), ov("Rotation", fmt(rot(r)))]
        # Overrides replace the prefab root's value, so Scale is needed whenever it differs from the generated root's.
        root_scale = [float(x) for x in str(generated_root.get("Scale", "1,1,1")).split(",")]
        if any(abs(a - b) > 1e-6 for a, b in zip(scl(s), root_scale)): overrides.append(ov("Scale", fmt(scl(s))))
        overrides.append(ov("Name", name))
        if not active: overrides.append(ov("Enabled", False))
        stub = {"__guid": instance_guid, "__version": 2, "__Prefab": doc_path,
                "__PrefabInstancePatch": {"AddedObjects": [], "RemovedObjects": [], "PropertyOverrides": overrides, "MovedObjects": []},
                "__PrefabIdToInstanceId": {root_guid: instance_guid}}
        if existing: existing.clear(); existing.update(stub); print(f"replaced instance {name} -> {doc_path}")
        else: objs.append(stub); print(f"added instance {name} -> {doc_path}")

    # --- Unity GameObject name / transform for a component block ------------------------
    def owner(body):
        go = ref_id(field(body, "m_GameObject"))
        name = unquote(field(unity[go][1], "m_Name") or "") if go in unity else ""
        tr = next((b for c, b, st in unity.values() if c in ("4", "224") and not st and ref_id(field(b, "m_GameObject")) == go), "")
        if tr and ref_id(field(tr, "m_Father")) != 0: problems.append(f"{name}: parented in Unity; only its local transform was applied")
        return name, vec(tr, "m_LocalPosition", "xyz"), vec(tr, "m_LocalRotation", "xyzw")

    def component(type_name):
        return next((o for o in objs for c in o.get("Components", []) if c.get("__type") == type_name), None)

    # --- Camera -------------------------------------------------------------------------
    cams = [b for c, b, st in unity.values() if c == "20" and not st]
    if cams:
        body = cams[0]
        name, p, r = owner(body)
        cam = component("Sandbox.CameraComponent")
        if cam is None: problems.append("target scene has no CameraComponent object; camera not converted")
        else:
            cc = next(c for c in cam["Components"] if c["__type"] == "Sandbox.CameraComponent")
            cam["Name"], cam["Position"], cam["Rotation"] = name or cam["Name"], fmt(pos(p)), fmt(rot(r))
            if field(body, "orthographic") == "1":
                cc["Orthographic"] = True
                cc["OrthographicHeight"] = round(float(field(body, "orthographic size")) * 2 * M, 3)
            cc["FieldOfView"] = float(field(body, "field of view"))
            if cc["FieldOfView"].is_integer(): cc["FieldOfView"] = int(cc["FieldOfView"])
            cc["FovAxis"] = "Horizontal" if field(body, "m_FOVAxisMode") == "1" else "Vertical"
            cc["ZNear"] = max(1, round(float(field(body, "near clip plane")) * M, 3))
            far = round(float(field(body, "far clip plane")) * M, 3)
            cc["ZFar"] = int(far) if float(far).is_integer() else far
            print(f"camera {cam['Name']}: fov {cc['FieldOfView']} {cc['FovAxis']}, near {cc['ZNear']}, far {cc['ZFar']}")
        if len(cams) > 1: problems.append(f"{len(cams)} Unity cameras; only the first was converted")

    # --- Directional light ----------------------------------------------------------------
    lights = [b for c, b, st in unity.values() if c == "108" and not st and field(b, "m_Type") == "1"]
    if lights:
        body = lights[0]
        name, p, r = owner(body)
        sun = component("Sandbox.DirectionalLight")
        if sun is None: problems.append("target scene has no DirectionalLight object; light not converted")
        else:
            dl = next(c for c in sun["Components"] if c["__type"] == "Sandbox.DirectionalLight")
            # Unity (linear colour space, as URP uses): linear(colour) x raw CCT(T) x intensity.
            # Verified in Unity 6000.3 via LightmapperUtils.Extract: the CCT factor is NOT linearised.
            color = [srgb_to_linear(c) for c in vec(body, "m_Color", "rgb")]
            if field(body, "m_UseColorTemperature") == "1":
                color = [a * b for a, b in zip(color, cct_rgb(float(field(body, "m_ColorTemperature"))))]
            intensity = float(field(body, "m_Intensity") or 1)
            color = [round(c * intensity, 5) for c in color]
            shadows = re.search(r"(?ms)^\s*m_Shadows:\s*\n\s*m_Type:\s*(\d+)", body)
            sun["Name"], sun["Position"], sun["Rotation"] = name or sun["Name"], fmt(pos(p)), fmt(rot(r))
            dl["LightColor"] = fmt(color + [1])
            dl["Shadows"] = bool(shadows and shadows.group(1) != "0")
            print(f"light {sun['Name']}: LightColor {dl['LightColor']}, shadows {dl['Shadows']}, rotation {sun['Rotation']}")
        if len(lights) > 1: problems.append(f"{len(lights)} Unity directional lights; only the first was converted")

    for pr in problems: print("PROBLEM", pr)
    if problems and not allow_partial: sys.exit(f"{len(problems)} problem(s); {target} left unchanged (--allow-partial writes it anyway)")
    text = json.dumps(scene, indent=2, ensure_ascii=False)
    if crlf: text = text.replace("\n", "\r\n")
    open(target, "wb").write(text.encode("utf-8"))

if __name__ == "__main__":
    main(sys.argv[1:])
